import{_ as i,l as n,o as e,c as o,v as r,p as m,x as t,d as l,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"Harrison–Kreps 鞅定价","description":"","frontmatter":{"title":"Harrison–Kreps 鞅定价","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/harrison-kreps-martingale.md","filePath":"econ/harrison-kreps-martingale.md","lastUpdated":1789023840000}'),E={name:"econ/harrison-kreps-martingale.md"};function b(d,a,c,A,B,_){const s=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="harrison–kreps-鞅定价" tabindex="-1">Harrison–Kreps 鞅定价 <a class="header-anchor" href="#harrison–kreps-鞅定价" aria-label="Permalink to &quot;Harrison–Kreps 鞅定价&quot;">​</a></h1><div class="epigraph"><p>可行的跨期交易若不容套利，资产价格在某个等价测度下是鞅；投机者可以意见不同，只要他们的交易仍落在这套价格上。</p><footer>—— Harrison and Kreps, Martingales and Arbitrage in Multiperiod Securities Markets, Journal of Economic Theory, 1979</footer></div><p><a href="/econ/dynamic-completeness">上一课</a>说明动态张成如何使 EMM 唯一。本课缺口是回到 1979 年原文的问题设定：多期证券、可行消费计划、以及<strong>信念可以不同</strong>时价格仍是鞅。不重做 Girsanov，不把异质信念写成行为泡沫课的再版——那一课已有 Harrison–Kreps 投机；这里要的是鞅定价作为 FTAP 的历史与逻辑核。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Harrison 与 Kreps 问：给定事件树与有限证券，怎样的价格过程使（适当定义的）可行策略不产生套利，并使有限生命的投资者能用证券实现消费。答案是：存在等价测度，折现价格为鞅；任何可复制的支付按鞅期望定价。信念异质时，每人有自己的 \\(\\mathbb{P}^i\\)，但无套利约束的是价格，不是信念——只要存在一个与「被定价的事件」相容的 \\(\\mathbb{Q}\\)，意见不同的人仍可以交易，价格不必等于任何一个人的 \\(\\mathrm{E}^{i}[m x]\\)。</p><p>缺口是把 FTAP 从「存在 \\(m\\)」写回原文的跨期可行集语言，并标明：鞅是对 \\(\\mathbb{Q}\\)，不是对每个投资者的 \\(\\mathbb{P}^i\\)。行为课序的投机泡沫用的是同一对作者的另一篇（1978, <em>QJE</em>）——短卖约束加异质信念。本课 1979 是套利与鞅；不要并成一篇。</p><p><span class="marginnote">Harrison and Kreps, <em>JET</em> 20, 1979。连续时间的 Harrison–Pliska 1981 把同样逻辑放到随机积分。本课以 1979 的离散多期为骨架。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义策略的可行：财富过程有下界（避免加倍策略那种「无限负债换套利」）。在此约束下 NA，分离给出 \\(\\mathbb{Q}\\)。定价：可复制权益的价格是 \\(\\mathrm{E}^{\\mathbb{Q}}[\\text{支付}/\\text{计价}]\\)，与任何 \\(\\mathbb{P}^i\\) 的主观期望都可以不同——差的部分是风险调整，或是意见，两者在仅有价格数据时分不开。这正是 <a href="/econ/emh">EMH</a> 联合假说在鞅语言里的样子。</p><p>完全时 \\(\\mathbb{Q}\\) 唯一，意见差异只能表现在持仓上，不能表现在价格上：价格被复制锁死。不完全时意见可以进入未被复制的方向的「价格」（若那些要求权被开出来），本课仍停在已上市证券。</p>',10)),(e(),m(h,null,{default:t(()=>[p(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FEAS%5B%22%E5%8F%AF%E8%A1%8C%E7%AD%96%E7%95%A5%20%2B%20%E4%B8%8B%E7%95%8C%22%5D%20--%3E%20NA%5B%22%E6%97%A0%E5%A5%97%E5%88%A9%22%5D%0A%20%20NA%20--%3E%20Q%5B%22%E5%AD%98%E5%9C%A8%20Q%20%E4%BD%BF%E6%8A%98%E7%8E%B0%E4%BB%B7%E6%A0%BC%E4%B8%BA%E9%9E%85%22%5D%0A%20%20BEL%5B%22%E5%BC%82%E8%B4%A8%20P%5Ei%22%5D%20--%3E%20TRD%5B%22%E4%BA%A4%E6%98%93%E5%8F%91%E7%94%9F%22%5D%0A%20%20Q%20--%3E%20PR%5B%22%E5%8F%AF%E5%A4%8D%E5%88%B6%E6%94%AF%E4%BB%98%E6%8C%89%20Q%20%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20BEL%20--%3E%20PR%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>不要把鞅定价写成「价格不可预测」。在 \\(\\mathbb{P}\\) 下价格可以有漂移；不可预测的是 \\(\\mathbb{Q}\\) 下的折现价格。Samuelson 1965 的「正确预期」接近 \\(\\mathbb{P}\\)–鞅，那是风险中性或已经折现好的特例。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是跨期预算的对偶。每一期的证券交易把财富在状态下搬家；套利是搬家后能免费改善消费。对偶变量在每个节点给出局部状态价格，串起来就是密度过程。异质信念不破坏对偶——破坏的是「\\(m\\) 来自同一个 \\(u&#39;(c)\\)」。均衡若要存在，还需要市场出清；FTAP 不管出清，只管给定价格过程是否可套利。Lucas 树下一课才把出清加回来，选出一个特定的 \\(m\\)。</p><p>加倍策略：若财富无下界，鞅变换仍可能让期望升——那是策略空间太大，不是 FTAP 失败。下界（或可积性）把免费午餐从「技术上的期望把戏」里关掉。</p><p><span class="marginnote">1978 的 <em>QJE</em> 投机：短卖约束使乐观者决定价格。1979 的 <em>JET</em>：无约束时价格由 \\(\\mathbb{Q}\\) 锁。两篇作者重叠，假设与结论不重叠。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计风险中性密度，不从期权表面反演 \\(q\\)——那是 Breeden–Litzenberger 的测量，偏量化。下一课把状态价格与 SDF 正式焊成一座桥，便于后文 Lucas 树用 \\(u&#39;(c)\\) 选出 \\(\\mathbb{Q}\\)。</p><p>后课默认：Harrison–Kreps 的鞅是 FTAP 的跨期形式；信念可异质，可复制价格仍由 \\(\\mathbb{Q}\\) 给出。财富下界是策略空间的一部分。1978 投机篇不是本课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可行策略无套利 ⇔ 存在使折现价格为鞅的 \\(\\mathbb{Q}\\)。</li><li>可复制支付按 \\(\\mathbb{Q}\\) 定价，不必等于任何主观 \\(\\mathrm{E}^{i}\\)。</li><li>鞅在 \\(\\mathbb{Q}\\) 下，不是「\\(\\mathbb{P}\\) 下不可预测」。</li><li>出处：Harrison and Kreps, <em>JET</em> 1979。</li></ul>',10))])}const T=i(E,[["render",b]]);export{P as __pageData,T as default};
